    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpStx = STX()
        tmpStx.Init(buf, pos)
        return cls.InitFromObj(tmpStx)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpStx):
        x = STXT()
        x._UnPack(tmpStx)
        return x

    # STXT
    def _UnPack(self, STX):
        if STX is None:
            return
        self.ID = STX.ID()
        self.SITE_ID = STX.SITE_ID()
        self.SITE_NATIVE_ID = STX.SITE_NATIVE_ID()
        self.STATION_NAME = STX.STATION_NAME()
        self.STATION_IDENTITY = STX.STATION_IDENTITY()
        self.FREQUENCY_KHZ = STX.FREQUENCY_KHZ()
        self.BANDWIDTH_KHZ = STX.BANDWIDTH_KHZ()
