        if self.VALID_UNTIL is not None:
            STXAddVALID_UNTIL(builder, VALID_UNTIL)
        if self.SEASON is not None:
            STXAddSEASON(builder, SEASON)
        if self.TARGET_AREA is not None:
            STXAddTARGET_AREA(builder, TARGET_AREA)
        if self.TARGET_ZONES is not None:
            STXAddTARGET_ZONES(builder, TARGET_ZONES)
        if self.LANGUAGE is not None:
            STXAddLANGUAGE(builder, LANGUAGE)
        STXAddTRANSMITTER_POWER_KW(builder, self.TRANSMITTER_POWER_KW)
        STXAddANTENNA_AZIMUTH_DEG(builder, self.ANTENNA_AZIMUTH_DEG)
        STXAddANTENNA_AZIMUTH_SECONDARY_DEG(builder, self.ANTENNA_AZIMUTH_SECONDARY_DEG)
        STXAddOMNIDIRECTIONAL(builder, self.OMNIDIRECTIONAL)
        if self.ANTENNA_DESIGNATION is not None:
            STXAddANTENNA_DESIGNATION(builder, ANTENNA_DESIGNATION)
        if self.EMISSION_ID is not None:
            STXAddEMISSION_ID(builder, EMISSION_ID)
        STXAddAUTHORITY(builder, self.AUTHORITY)
        STXAddSTATUS(builder, self.STATUS)
        if self.FIRST_OBSERVED is not None:
            STXAddFIRST_OBSERVED(builder, FIRST_OBSERVED)
        if self.LAST_OBSERVED is not None:
            STXAddLAST_OBSERVED(builder, LAST_OBSERVED)
        STXAddOBSERVATION_COUNT(builder, self.OBSERVATION_COUNT)
        if self.SOURCES is not None:
            STXAddSOURCES(builder, SOURCES)
        STX = STXEnd(builder)
        return STX
